create table if not exists public.putra_transaksi(id uuid primary key default gen_random_uuid(),unit text not null default 'putra',tanggal date not null,no_transaksi text unique not null,jenis text not null check(jenis in('pemasukan','pengeluaran')),kategori text not null,akun text not null,nominal numeric not null default 0,keterangan text,created_at timestamptz default now());
create table if not exists public.putra_laporan_harian(id uuid primary key default gen_random_uuid(),unit text not null default 'putra',tanggal date not null,pendapatan_i numeric default 0,pendapatan_ii numeric default 0,titipan_i numeric default 0,titipan_ii numeric default 0,titipan_iii numeric default 0,tabungan numeric default 0,total numeric default 0,created_at timestamptz default now());
create table if not exists public.putra_tabungan(id uuid primary key default gen_random_uuid(),unit text not null default 'putra',tanggal date not null,jenis text not null check(jenis in('setoran','penarikan')),nominal numeric not null default 0,keterangan text,created_at timestamptz default now());
alter table public.putra_transaksi enable row level security; alter table public.putra_laporan_harian enable row level security; alter table public.putra_tabungan enable row level security;
create policy "putra transaksi auth" on public.putra_transaksi for all to authenticated using(unit='putra') with check(unit='putra');
create policy "putra laporan auth" on public.putra_laporan_harian for all to authenticated using(unit='putra') with check(unit='putra');
create policy "putra tabungan auth" on public.putra_tabungan for all to authenticated using(unit='putra') with check(unit='putra');
